// Turn a Gumroad sale ping into one Airtable row, or reject it with a reason.
// Gumroad sends price in cents as a string: "1250" means 12.50.

const MAX_REASON = 200;

function maskEmail(value) {
  const s = String(value || "");
  const at = s.indexOf("@");
  if (at < 1) return "";
  const user = s.slice(0, at);
  const domain = s.slice(at + 1);
  const head = user.slice(0, Math.min(2, user.length));
  return head + "*".repeat(Math.max(1, user.length - head.length)) + "@" + domain;
}

function amountFromPrice(price) {
  if (price === null || price === undefined || price === "") return null;
  const n = Number(price);
  if (!Number.isFinite(n) || n < 0) return null;
  return Math.round(n) / 100;
}

function dateFrom(value) {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) {
    return { iso: new Date().toISOString(), estimated: true };
  }
  return { iso: d.toISOString(), estimated: false };
}

function isEmail(value) {
  const s = String(value || "").trim();
  const at = s.indexOf("@");
  return at > 0 && at < s.length - 1 && s.indexOf(" ") === -1;
}

function reject(reason, saleId, email) {
  return {
    status: "REJECTED",
    reason: reason,
    sale_id: String(saleId || ""),
    email_masked: maskEmail(email),
    fields: null,
  };
}

function normalise(body) {
  const saleId = String((body && body.sale_id) || "").trim();
  if (!saleId) return reject("missing_sale_id", "", "");

  const email = String((body && body.email) || "").trim();
  if (!isEmail(email)) return reject("invalid_email", saleId, email);

  const amount = amountFromPrice(body && body.price);
  if (amount === null) return reject("price_not_a_number", saleId, email);

  const when = dateFrom(body && body.sale_timestamp);

  return {
    status: "READY",
    reason: "",
    sale_id: saleId,
    email_masked: maskEmail(email),
    date_estimated: when.estimated,
    fields: {
      sale_id: saleId,
      email: email,
      sold_at: when.iso,
      amount: amount,
      currency: String((body && body.currency) || "usd").toUpperCase(),
      product_id: String((body && body.product_id) || ""),
      product_name: String((body && body.product_name) || ""),
      order_number: String((body && body.order_number) || ""),
      country: String((body && body.ip_country) || ""),
      test_sale: body && (body.test === true || body.test === "true"),
    },
  };
}

const out = [];
for (const item of $input.all()) {
  const raw = item.json || {};
  const body = raw.body !== undefined ? raw.body : raw;
  out.push({ json: normalise(body) });
}
return out;

// Decide what the run log should say, based on what Airtable returned.
// 429 and 5xx are worth retrying later. Other 4xx will never succeed: retrying
// only piles up failed rows.

const MAX_REASON = 200;

function classify(httpStatus, message) {
  const code = Number(httpStatus) || 0;
  const text = String(message || "");
  if (code === 429) return { retryable: true, kind: "TEMPORARY", reason: "rate_limited" };
  if (code >= 500) return { retryable: true, kind: "TEMPORARY", reason: "server_error_" + code };
  if (code === 0 && /timeout|ETIMEDOUT|ECONNRESET|EAI_AGAIN/i.test(text)) {
    return { retryable: true, kind: "TEMPORARY", reason: "network" };
  }
  if (code >= 400) return { retryable: false, kind: "PERMANENT", reason: "rejected_" + code };
  return { retryable: false, kind: "PERMANENT", reason: "unknown_error" };
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const code = Number(j.statusCode) || 0;
  const ok = code >= 200 && code < 300;
  const info = ok
    ? { retryable: false, kind: "OK", reason: "" }
    : classify(code, j.error || j.message || "");

  out.push({
    json: {
      sale_id: String(j.sale_id || ""),
      email_masked: String(j.email_masked || ""),
      action: ok ? "WROTE_ROW" : "WRITE_FAILED",
      status: info.kind,
      reason: String(info.reason).slice(0, MAX_REASON),
      retryable: info.retryable,
      attempts: 1,
      at: new Date().toISOString(),
    },
  });
}
return out;

// Log a rejected ping. The row still gets recorded, so a malformed sale is
// visible instead of disappearing.

const MAX_REASON = 200;

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  out.push({
    json: {
      sale_id: String(j.sale_id || ""),
      email_masked: String(j.email_masked || ""),
      action: "REJECTED_PING",
      status: "REJECTED",
      reason: String(j.reason || "").slice(0, MAX_REASON),
      retryable: false,
      attempts: 1,
      at: new Date().toISOString(),
    },
  });
}
return out;
